import React from 'react'
import axios from 'axios'

const HACKERWATCH = axios.create({
    baseURL: 'https://www.hackerwatch.org/health/v1/',

});

class HackerWatch extends React.Component {
    constructor() {
        super();

        this.state = {
            results: []
        };
    }

    componentDidMount() {
        this.getHealthCheckResult();
    }

    getHealthCheckResult() {
        HACKERWATCH.get('https://www.hackerwatch.org/health/v1/', (req, res) => {
            return res.json()
                .then((data) => this.setState({ results: data }))
        });
    }

    render() {
        console.log(this.state.results);
        return (
            <div>
                <h1>
                    HackerWatch.org Results
        </h1>
                <h2>
                    Basic
          </h2>
                <p>{this.state.results.basic}</p>
                <h2>
                    Extended
          </h2>
                <p>{this.state.results.extended}</p>
            </div>
        )
    }
}

export default HackerWatch;
